function searchInsert(nums: number[], target: number): number {
  // Ищем первый индекс, где nums[i] >= target, на полуинтервале [lo, hi).
  // hi = nums.length: target может оказаться больше всех элементов
  let lo = 0;
  let hi = nums.length;

  while (lo < hi) {
    // Середина без риска переполнения
    const mid = lo + ((hi - lo) >> 1);

    if (nums[mid] < target) {
      // mid и всё левее него меньше target — ответ строго правее
      lo = mid + 1;
    } else {
      // nums[mid] >= target — mid подходит, но может быть и левее
      hi = mid;
    }
  }

  // lo === hi — первая позиция, где элемент >= target
  // (это и индекс найденного элемента, и место вставки)
  return lo;
}

// Время: O(log n) — каждый шаг вдвое сужает диапазон
// Память: O(1)
